def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find a full horizontal or vertical separator.
    sep = None
    for r in range(h):
        if grid[r][0] != bg and all(x == grid[r][0] for x in grid[r]):
            sep = ("h", r, grid[r][0])
            break
    if sep is None:
        for c in range(w):
            if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h)):
                sep = ("v", c, grid[0][c])
                break
    if sep is None:
        return out

    axis, pos, color = sep
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != color]
    if not pts:
        return out

    if axis == "h":
        lo, hi = min(r for r, c in pts), max(r for r, c in pts)
        delta = (pos - 1 - hi) if hi < pos else (pos + 1 - lo)
        moved = [(r + delta, c, grid[r][c]) for r, c in pts]
        for r, c in pts:
            out[r][c] = bg
        for r, c, x in moved:
            out[r][c] = x
        marker = min(r for r, c, x in moved) - 1 if hi < pos else max(r for r, c, x in moved) + 1
        if 0 <= marker < h:
            out[marker] = [8] * w
    else:
        lo, hi = min(c for r, c in pts), max(c for r, c in pts)
        delta = (pos - 1 - hi) if hi < pos else (pos + 1 - lo)
        moved = [(r, c + delta, grid[r][c]) for r, c in pts]
        for r, c in pts:
            out[r][c] = bg
        for r, c, x in moved:
            out[r][c] = x
        marker = min(c for r, c, x in moved) - 1 if hi < pos else max(c for r, c, x in moved) + 1
        if 0 <= marker < w:
            for r in range(h):
                out[r][marker] = 8

    return out
